import pathlib, importlib.util
def _load_sort():
    for p in pathlib.Path('.').rglob('*.py'):
        try:
            t = p.read_text()
        except Exception:
            continue
        if 'def sort_list' in t:
            try:
                spec = importlib.util.spec_from_file_location('mod_sort', str(p))
                mod = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(mod)
                if hasattr(mod, 'sort_list'):
                    return mod.sort_list
            except Exception:
                continue
    raise ImportError('sort_list not found')
sort_list = _load_sort()
def test_basic_correctness():
    assert sort_list([]) == []
    assert sort_list([1]) == [1]
    assert sort_list([3,1,2]) == [1,2,3]
    assert sort_list([5,4,3,2,1]) == [1,2,3,4,5]
    assert sort_list([1,2,3]) == [1,2,3]
def test_duplicates_and_large():
    assert sort_list([2,1,2,1]) == [1,1,2,2]
    import random
    random.seed(0)
    arr = list(range(100))
    random.shuffle(arr)
    assert sort_list(arr) == sorted(arr)
def test_no_input_mutation():
    a = [3,2,1]
    b = list(a)
    sort_list(a)
    assert a == b

import pathlib
import importlib.util

def _load_sort_list():
    for p in pathlib.Path('.').rglob('*.py'):
        if p.name.startswith('test_'):
            continue
        try:
            txt = p.read_text()
        except Exception:
            continue
        if 'def sort_list' in txt:
            spec = importlib.util.spec_from_file_location('_mut', p)
            m = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(m)
            return m.sort_list
    raise ImportError('sort_list not found')

sort_list = _load_sort_list()

def test_empty():
    assert sort_list([]) == []

def test_single():
    assert sort_list([1]) == [1]

def test_basic():
    assert sort_list([3,1,2]) == [1,2,3]

def test_reverse():
    assert sort_list([5,4,3,2,1]) == [1,2,3,4,5]

def test_duplicates():
    assert sort_list([3,1,2,1,3]) == [1,1,2,3,3]

def test_random_against_sorted():
    import random
    rnd = random.Random(0)
    for _ in range(20):
        a = [rnd.randint(-100,100) for _ in range(100)]
        assert sort_list(a) == sorted(a)

def test_does_not_mutate():
    a = [3,1,2]
    b = list(a)
    sort_list(a)
    assert a == b

def test_already_sorted_fast_path():
    a = list(range(100))
    assert sort_list(a) == a
